already exist.\\n\\n## Screenshots\\n\\nFree text dosage switched on, label now reads \\\"On\\\":\\n\\n<img width=\\\"636\\\" height=\\\"972\\\" alt=\\\"Fix\\\" src=\\\"https://github.com/user-attachments/assets/1a6090c8-7d65-4804-8c11-c9dacac6cc2a\\\" />\\n\\n## Related Issue\\n\\nhttps://issues.openmrs.org/browse/O3-6097\\n\\n## Other\\n\\nN/A\\n\",\"freshness\":[{\"repo\":\"github.com/openmrs/openmrs-esm-patient-chart\",\"lastSyncedAt\":\"2026-10-24T04:03:34.106Z\",\"stale\":false}],\"nextOffset\":null,\"truncated\":[]}"}],"tool_result_meta":[{"id":"toolu_01NHtgnM7GjuXo46Z7i1tx8d","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
